with scored as (select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, avg(humidity) over (partition by device_code order by reading_ts, id rows between 2 preceding and current row) as humidity_avg_2, lag(humidity, 1) over (partition by device_code order by temp_c, id) as prev_humidity, round(humidity / sum(humidity) over (partition by device_code), 4) as humidity_share from device_readings) select id, reading_ts, firmware, humidity_avg_2, prev_humidity, humidity_share from scored
